<div id="app-content"><div id="app-content-wrapper"><?php print_unescaped($this->inc('_nav')); ?><main class="erp-main"><div class="erp-head"><div><h1><?=p($project['project_no'].' · '.$project['title'])?></h1><p>Kunde: <?=p($project['customer_no'].' '.$project['customer_name'])?> · Status: <?=p($project['status'])?></p></div><a class="button primary" href="<?=p(\OC::$server->getURLGenerator()->linkToRoute('reinhardterp.page.projectForm',['id'=>$project['id']]))?>">Bearbeiten</a></div><div class="erp-grid"><section class="erp-card"><h2>Projekt</h2><p><?=nl2br(p($project['description']??''))?></p><p><b>Ordner:</b><br><?=p($project['folder_path']??'')?></p></section><section class="erp-card"><h2>Summen</h2><p><b><?=count($reports)?></b> Rapporte</p><p><b><?=array_sum(array_map(fn($x)=>(float)$x['hours'],$times))?></b> erfasste Stunden</p></section></div><section class="erp-card"><h2>Rapporte</h2><table><tr><th>Nr.</th><th>Datum</th><th>Titel</th><th>Status</th></tr><?php foreach($reports as $x):?><tr><td><a href="<?=p(\OC::$server->getURLGenerator()->linkToRoute('reinhardterp.module.reportDetail',['id'=>$x['id']]))?>"><?=p($x['report_no'])?></a></td><td><?=p($x['report_date'])?></td><td><?=p($x['title'])?></td><td><?=p($x['status'])?></td></tr><?php endforeach;?></table></section><section class="erp-card"><h2>Zeiterfassung</h2><table><tr><th>Datum</th><th>Mitarbeiter</th><th>Stunden</th><th>Tätigkeit</th></tr><?php foreach($times as $x):?><tr><td><?=p($x['work_date'])?></td><td><?=p($x['user_id'])?></td><td><?=p($x['hours'])?></td><td><?=p($x['activity'])?></td></tr><?php endforeach;?></table></section></main></div></div>
